{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Support for life transitions</title>
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <header class="nav">
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="about.html">Who I am</a>
      <a href="specialties.html">Areas</a>
      <a href="approach.html">Approach</a>
      <a href="fees.html">Programs</a>
      <a href="book.html" class="cta-link">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>

    <section class="hero">
      <div class="hero-inner">
        <h1>Practical support for when life shifts — steady, specific, private</h1>
        <p class="lead">Sessions and short programs to help you notice what matters and take the next careful steps.</p>
        <a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
      <svg class="bg-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"></use></svg>
    </section>

    <section class="social-proof">
      <h2>Notes from clients</h2>
      <ul>
        <li>"Helped me make a plan I could actually try." — A.</li>
        <li>"Clear, realistic guidance when I felt stuck." — R.</li>
      </ul>
    </section>

    <section class="benefits">
      <h2>How people typically work together</h2>
      <div class="pricing-card">
        <div class="price-toggle" role="tablist" aria-label="Pricing mode">
          <button data-mode="monthly" class="active" aria-pressed="true">Monthly</button>
          <button data-mode="package" aria-pressed="false">Package</button>
        </div>
        <ul class="plans">
          <li>
            <h3>Support Track</h3>
            <p class="desc">Ongoing sessions (weekly or every other week) to maintain steady progress.</p>
            <div class="price" data-monthly="140" data-package="1200">$<span>140</span><small>/mo</small></div>
          </li>
          <li>
            <h3>Focused Series</h3>
            <p class="desc">A 6-session series designed to address a well-defined concern.</p>
            <div class="price" data-monthly="170" data-package="900">$<span>170</span><small>/session</small></div>
          </li>
          <li>
            <h3>Short Intensive</h3>
            <p class="desc">Two deep sessions to map immediate next steps and reduce uncertainty.</p>
            <div class="price" data-monthly="0" data-package="350">$<span>350</span><small>/package</small></div>
          </li>
        </ul>
      </div>
    </section>

    <section class="process">
      <h2>Mood → Method</h2>
      <p class="process-lead">Select what best matches how you feel now — the suggested approach and the booking prompt will update to reflect it.</p>
      <div class="mood-selector" role="tablist" aria-label="Mood selector">
        <button data-mood="overwhelmed">Overwhelmed</button>
        <button data-mood="stuck">Stuck</button>
        <button data-mood="transition">In transition</button>
        <button data-mood="curious">Seeking clarity</button>
      </div>
      <div class="method-card">
        <h3 class="method-title">Recommended: Stabilize & Sort</h3>
        <p class="method-desc">A short set of sessions to reduce load and identify small, manageable changes.</p>
        <a class="method-cta primary-cta" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
      </div>
    </section>

    <section class="faq">
      <h2>Practice notes</h2>
      <ul>
        <li>Sessions are confidential within professional and legal limits; details are discussed at intake.</li>
        <li>I provide psychotherapy and supportive counseling. This site is informational, not a replacement for urgent care.</li>
        <li>If you are in immediate danger or a crisis, call local emergency services or a crisis line right away.</li>
      </ul>
    </section>

    <section class="cta-lower">
      <h2>Ready to take a next step?</h2>
      <p>Reach out to book a brief consult or to ask which program fits what you need now.</p>
      <a class="primary-cta" href="book.html">See available times</a>
    </section>

  </main>

  <footer>
    <div class="footer-inner">{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>
</body>
</html>"} 
