{"path":"assets/css/styles.css","content":":root{
  --bg:#0f1724;
  --card:rgba(255,255,255,0.06);
  --glass:rgba(255,255,255,0.08);
  --accent:#8bd3c7;
  --muted:#cbd5e1;
  --cta:#2dd4bf;
  --text:#e6eef1;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--text);background:linear-gradient(180deg,#071023 0%, #0b1624 100%);-webkit-font-smoothing:antialiased}
header.nav{display:flex;justify-content:space-between;align-items:center;padding:18px 28px;background:transparent}
header .brand{font-weight:600}
header nav a{color:var(--muted);margin-left:18px;text-decoration:none}
header nav .cta-link{background:rgba(255,255,255,0.06);padding:8px 12px;border-radius:8px;color:var(--text)}
.hero{position:relative;padding:64px 24px;display:flex;align-items:center;justify-content:center;min-height:320px}
.hero-inner{max-width:820px;text-align:center;background:linear-gradient(135deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border-radius:14px;padding:36px;backdrop-filter:blur(8px);box-shadow:0 8px 30px rgba(2,6,23,0.6)}
.hero h1{font-size:clamp(20px,3.6vw,38px);margin:0 0 12px}
.hero .lead{color:var(--muted);margin:0 0 18px}
.primary-cta{display:inline-block;background:var(--cta);color:#012021;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.bg-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.08;pointer-events:none}
.social-proof, .benefits, .process, .faq, .cta-lower{max-width:980px;margin:28px auto;padding:18px}
.social-proof h2,.benefits h2,.process h2,.faq h2{margin:0 0 12px}
.pricing-card{background:var(--card);padding:18px;border-radius:12px;backdrop-filter:blur(6px)}
.price-toggle{display:inline-flex;border-radius:10px;overflow:hidden;border:1px solid rgba(255,255,255,0.04);margin-bottom:12px}
.price-toggle button{background:transparent;border:0;color:var(--muted);padding:8px 12px;cursor:pointer}
.price-toggle button.active{background:linear-gradient(90deg, rgba(45,212,191,0.12), rgba(139,211,199,0.08));color:var(--text)}
.plans{list-style:none;padding:0;margin:6px 0 0;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.plans li{background:var(--glass);padding:12px;border-radius:10px}
.plans h3{margin:0 0 6px}
.plans .desc{color:var(--muted);margin:0 0 8px}
.price{font-weight:700;font-size:18px}
.price small{color:var(--muted);margin-left:6px;font-weight:600}
.mood-selector{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}
.mood-selector button{background:transparent;border:1px solid rgba(255,255,255,0.04);padding:8px 10px;border-radius:8px;color:var(--muted);cursor:pointer}
.mood-selector button.active{background:linear-gradient(90deg, rgba(139,211,199,0.12), rgba(45,212,191,0.06));color:var(--text)}
.method-card{margin-top:12px;padding:14px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border-radius:10px}
.method-title{margin:0 0 6px}
.method-desc{margin:0 0 8px;color:var(--muted)}
.method-cta{display:inline-block;text-decoration:none;padding:8px 12px;border-radius:8px;background:var(--accent);color:#042623;font-weight:600}
.method-title.mutate, .method-desc.mutate, .method-cta.mutate{opacity:0.2;transform:translateY(6px);transition:all 220ms ease}
.method-title, .method-desc, .method-cta{transition:all 240ms ease}
.faq ul{color:var(--muted)}
footer{padding:24px 20px;text-align:center;color:var(--muted);font-size:13px}
@media (min-width:900px){
  header nav a{margin-left:22px}
  .hero{padding:84px 24px}
}
"}
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded', function(){
  // Pricing comparator toggle
  var toggleBtns = Array.from(document.querySelectorAll('.price-toggle button'));
  var priceEls = Array.from(document.querySelectorAll('.price'));

  function animateNumber(el, from, to){
    var span = el.querySelector('span');
    var duration = 420;
    var start = null;
    function step(ts){
      if(!start) start = ts;
      var progress = Math.min((ts - start)/duration, 1);
      var value = Math.round(from + (to - from) * progress);
      span.textContent = value;
      if(progress < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  toggleBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      toggleBtns.forEach(function(b){ b.classList.remove('active'); b.setAttribute('aria-pressed','false'); });
      btn.classList.add('active'); btn.setAttribute('aria-pressed','true');
      var mode = btn.getAttribute('data-mode');
      priceEls.forEach(function(p){
        var current = parseInt(p.querySelector('span').textContent, 10) || 0;
        var target = parseInt(p.getAttribute(mode === 'monthly' ? 'data-monthly' : 'data-package'), 10) || 0;
        animateNumber(p, current, target);
        var small = p.querySelector('small');
        if(mode === 'monthly'){
          // try to pick a suitable label
          if(target > 0) small.textContent = '/mo'; else small.textContent = '/session';
        } else {
          small.textContent = '/package';
        }
      });
    });
  });

  // Mood-to-Method selector
  var moodBtns = Array.from(document.querySelectorAll('.mood-selector button'));
  var methodTitle = document.querySelector('.method-title');
  var methodDesc = document.querySelector('.method-desc');
  var methodCta = document.querySelector('.method-cta');

  var map = {
    overwhelmed: {
      title: 'Calm & Stabilize',
      desc: 'Short, steady sessions to reduce immediate load and create small, safety-focused steps.',
      cta: 'Request a short consult'
    },
    stuck: {
      title: 'Map & Move',
      desc: 'A focused series that names patterns and tests small changes to shift them over time.',
      cta: 'Explore focused series'
    },
    transition: {
      title: 'Transition Support',
      desc: 'Flexible planning sessions to balance practical tasks and emotional transitions.',
      cta: 'Talk about a plan'
    },
    curious: {
      title: 'Clarity Sessions',
      desc: 'One or two targeted sessions to surface priorities and decide next steps with greater confidence.',
      cta: 'Book a clarity session'
    }
  };

  moodBtns.forEach(function(b){
    b.addEventListener('click', function(){
      moodBtns.forEach(function(x){ x.classList.remove('active'); });
      b.classList.add('active');
      var m = b.getAttribute('data-mood');
      var data = map[m] || {};
      // small morph animation
      [methodTitle, methodDesc, methodCta].forEach(function(n){ n.classList.add('mutate'); });
      setTimeout(function(){
        methodTitle.textContent = data.title || 'Recommended';
        methodDesc.textContent = data.desc || '';
        methodCta.textContent = data.cta || 'Start a conversation';
        // Update CTA target with a query hint to carry the chosen focus
        methodCta.setAttribute('href', 'book.html?focus=' + encodeURIComponent(data.title || 'Conversation'));
        [methodTitle, methodDesc, methodCta].forEach(function(n){ n.classList.remove('mutate'); });
      }, 180);
    });
  });

  // Initialize numeric displays to monthly values
  var initialMode = 'monthly';
  priceEls.forEach(function(p){
    var v = parseInt(p.getAttribute('data-' + initialMode), 10) || 0;
    p.querySelector('span').textContent = v;
  });
});"} 
